function BLX_check() {
  var u = 'https://www.bilixs.com/search.html?searchkey=' + encodeURIComponent('斗破苍穹');
  var body = '';
  try { body = String(java.ajax(u + ',{"webView":true}')); } catch (e) {}
  if (body.indexOf('module-search-item') >= 0) {
    java.toast('✅ 搜索通道正常（WebView 通道已通），可直接搜索');
  } else if (body.indexOf('请稍候') >= 0 || body.indexOf('Just a moment') >= 0 || body.indexOf('challenge-platform') >= 0) {
    java.toast('⛔ WebView 通道仍被拦：请点「打开浏览器过盾」，如出现验证按钮请手动点一下');
  } else {
    java.toast('⚠️ 搜索通道异常：响应 ' + (body ? body.length + ' 字符（非盾页）' : '为空'));
  }
}
