ruleSearch.bookList:
@js:(function(){
  var body = String(result || '');
  var u = '';
  try { u = String(java.get('blxUrl') || ''); } catch (e0) {}
  if (!u || u == 'null' || u == 'undefined') { u = String(baseUrl); }
  var diag = [];
  function D(k, v) { diag.push(k + '=' + v); try { source.put('blxDiag', new Date().toLocaleString() + ' || ' + diag.join(' | ')); } catch (e) {} }
  function hasList(h) { return String(h || '').indexOf('module-search-item') >= 0; }
  function isChallenge(h) {
    return h.indexOf('请稍候') >= 0 || h.indexOf('Just a moment') >= 0
      || h.indexOf('challenge-platform') >= 0 || h.indexOf('cf-chl') >= 0;
  }
  function parse(h) {
    var doc = org.jsoup.Jsoup.parse(h);
    var els = doc.select('div.module-search-item');
    var list = new Packages.java.util.ArrayList();
    for (var i = 0; i < els.size(); i++) { list.add(els.get(i)); }
    return list;
  }
  function grab() { try { return String(java.webView(null, u, null)); } catch (e) { D('grabErr', String(e).slice(0, 60)); return ''; } }
  // 温和重试：站点限频呈「正常页/错误页」交替出现，间隔拉长后大概率命中正常页
  function retryGrab(times, gap) {
    for (var i = 0; i < times; i++) {
      try { Packages.java.lang.Thread.sleep(gap); } catch (eS) {}
      var h = grab();
      D('retry' + i + 'Len', h.length);
      D('retry' + i + 'HasList', hasList(h));
      if (hasList(h)) { return h; }
    }
    return '';
  }
  D('upstreamLen', body.length);
  D('upstreamHasList', hasList(body));
  // 快路径：上游已是结果页
  if (hasList(body)) { D('path', 'upstream'); return parse(body); }
  // 常规：主动走 WebView（带书源 header 与过盾 Cookie）
  var h = grab();
  D('grabLen', h.length);
  D('grabHasList', hasList(h));
  D('grabChallenge', isChallenge(h));
  if (hasList(h)) { D('path', 'webview'); return parse(h); }
  // 非挑战页且无列表 → 限频/错误页（非 CF 挑战，弹浏览器无效）：温和重试 3 次、间隔 4 秒
  if (!isChallenge(h)) {
    h = retryGrab(3, 4000);
    if (hasList(h)) { D('path', 'retry-ok'); return parse(h); }
    // 温和重试仍无列表：确认是否已转成挑战页
    h = grab();
    if (isChallenge(h)) { D('path', 'now-challenge'); }
  }
  // 挑战页 → 弹内置浏览器过盾 → 再取（过盾后再温和重试兜底限频）
  if (isChallenge(h)) {
    try {
      java.toast('搜索通道安全检查中：弹出页面过盾（如出现验证按钮请手动点一下），完成后自动继续搜索');
      java.startBrowserAwait(u, '哔哩小说·安全检查（如出现验证按钮请手动点一下）');
      D('await', 'done');
      h = grab();
      D('regrabHasList', hasList(h));
      if (!hasList(h) && !isChallenge(h)) { h = retryGrab(2, 4000); }
      if (hasList(h)) { D('path', 'await+webview'); return parse(h); }
      java.toast('安全检查未完成：请重新搜索一次');
    } catch (e) {
      D('awaitErr', String(e).slice(0, 80));
      java.toast('安全检查未能自动打开：请到书源菜单「登录」点「打开浏览器过盾」后再搜索');
    }
  }
  return [];
})()

